from frappe.utils import now_datetime
import datetime

tanks = frappe.get_all("Hatchery Tank", filters={"status": "Active"}, fields=["name", "last_algae_feed_time", "last_artemia_feed_time"])

for tank in tanks:
    status = "On Schedule"
    current = now_datetime()

    if tank.last_algae_feed_time:
        diff = (current - tank.last_algae_feed_time).total_seconds() / 3600
        if diff > 1:
            status = "Algae Overdue"

    if tank.last_artemia_feed_time:
        diff = (current - tank.last_artemia_feed_time).total_seconds() / 3600
        if diff > 4:
            status = "Artemia Overdue"

    frappe.db.set_value("Hatchery Tank", tank.name, "feed_status", status)

batch = doc.shrimp_batch

if batch:

    batch_doc = frappe.get_doc("Shrimp Batch", batch)

    total_required = 0

    for row in batch_doc.shrimp_batch_tank:
        tank = frappe.get_doc("Hatchery Tank", row.tank)

        required = (tank.current_water_level or 0) * ((tank.daily_water_change or 0) / 100)
        total_required += required

    # Calculate available final stage water
    final_res = frappe.get_all(
        "Reservoir",
        filters={
            "treatment_stage": "Final",
            "process_status": "Ready for Tank"
        },
        fields=["current_volume"]
    )

    available = sum(r.current_volume or 0 for r in final_res)

    deficit = total_required - available

    status = "Sufficient"

    if deficit > 0:
        status = "Shortage"

    if available < (total_required * 0.5):
        status = "Critical"

    frappe.db.set_value("Shrimp Batch", batch, {
        "total_daily_water_required": total_required,
        "available_final_water": available,
        "water_deficit": deficit,
        "water_supply_status": status
    })

from_res = frappe.get_doc("Reservoir", doc.from_reservoir)
to_res = frappe.get_doc("Reservoir", doc.to_reservoir)

# Source must have water
if not from_res.current_volume or from_res.current_volume <= 0:
    frappe.throw("Source reservoir is empty.")

# FULL VOLUME ONLY
if doc.volume != from_res.current_volume:
    frappe.throw("Only full-volume transfer allowed. Transfer entire source volume.")

# Destination must be empty
if to_res.current_volume and to_res.current_volume > 0:
    frappe.throw("Destination reservoir must be empty before transfer.")

# Source must be ready
if from_res.process_status != "Ready for Next Stage":
    frappe.throw("Source reservoir not ready for transfer.")

# Destination must be active
if to_res.reservoir_status != "Active":
    frappe.throw("Destination reservoir not Active.")

frappe.db.set_value("Reservoir Transfer", doc.name, {
    "validation_status": "Valid"
})

res = frappe.get_doc("Reservoir", doc.reservoir)
tank = frappe.get_doc("Hatchery Tank", doc.tank)

# Stage validation
if res.treatment_stage != "Final":
    frappe.throw("Only Final Stage water can be supplied to tanks.")

# Status validation
if res.process_status != "Ready for Tank":
    frappe.throw("Reservoir not ready for tank supply.")

# Volume validation
if doc.volume > (res.current_volume or 0):
    frappe.throw("Insufficient water in reservoir.")

# Tank capacity validation
if (tank.current_water_level or 0) + doc.volume > (tank.capacity or 0):
    frappe.throw("Tank capacity exceeded.")

frappe.db.set_value("Tank Water Supply", doc.name, {
    "supply_status": "Valid"
})

res = frappe.get_doc("Reservoir", doc.reservoir)
tank = frappe.get_doc("Hatchery Tank", doc.tank)

# Deduct reservoir volume
new_res_volume = (res.current_volume or 0) - doc.volume

frappe.db.set_value("Reservoir", res.name, {
    "current_volume": new_res_volume
})

# Increase tank water
new_tank_volume = (tank.current_water_level or 0) + doc.volume

frappe.db.set_value("Hatchery Tank", tank.name, {
    "current_water_level": new_tank_volume
})

# If reservoir becomes empty
if new_res_volume <= 0:
    frappe.db.set_value("Reservoir", res.name, {
        "process_status": "Idle"
    })

# Check status
if doc.status != "Approved":
    frappe.throw("❌ Only Approved entries can be submitted")

# Check user
if frappe.session.user != doc.expense_approver:
    frappe.throw("❌ Only Expense Approver can  Approve ") 

for row in doc.expense_advance_item:
    
    if not row.advance_reference:
        continue

    if not row.allocate_amount or row.allocate_amount <= 0:
        continue

    advance = frappe.get_doc("Advance Entry", row.advance_reference)

    # Update used
    advance.used_amount = (advance.used_amount or 0) + row.allocate_amount

    # Correct balance calculation
    advance.balance_amount = (advance.amount or 0) - advance.used_amount

    # Prevent negative
    if advance.balance_amount < 0:
        advance.balance_amount = 0

    # Status update
    if advance.balance_amount == 0:
        advance.status = "Closed"

    advance.save(ignore_permissions=True)

if doc.previous_batch:

    previous_doc = frappe.get_doc("Algae Production Batch", doc.previous_batch)

    previous_doc.status = "Completed"

    previous_doc.save(ignore_permissions=True)


for row in doc.tank_allocation:

    if not row.algae_tank:
        continue

    frappe.db.set_value(
        "Hatchery Tank",
        row.algae_tank,
        {
            "harvest_status": 1,
            "initial_algae_volume": row.total_volume
        }
    )

existing = frappe.db.exists(
    "Daily Micro Checks",
    {
        "date": doc.date,
        "shed": doc.shed,
        "round": doc.round,
        "docstatus": ["!=", 2]
    }
)

if existing and existing != doc.name:
    frappe.throw(
        f"Already Microchecks Log updated for {doc.shed} - {doc.round} shift on {doc.date}."
    )

existing = frappe.db.exists(
    "Daily Visual Checks",
    {
        "date": doc.date,
        "shed": doc.shed,
        "round": doc.round,
        "docstatus": ["!=", 2]
    }
)

if existing and existing != doc.name:
    frappe.throw(
        f"Already Visual Log updated for {doc.shed} - {doc.round} shift on {doc.date}."
    )
